async function centerDrop(q){await tick(5);await center(q);await tick(4);for(const a of ['x','z'])if(bot.entity.position[a]<q[a]+.33||bot.entity.position[a]>q[a]+.67)throw Error('DROP_CENTER_POST');}
async function immediateBurial(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();for(let k=0;k<12&&!bot.entity.onGround;k++)await tick(1);const q=bot.entity.position.floored().offset(0,-1,0);if(!bot.entity.onGround||!cheapColumn(q))return false;await centerDrop(q);if(!cheapColumn(q))return false;global.P1DownPending={feet:q.offset(0,-2,0),roof:q,at:Date.now()};let steps=0;try{for(let y=0;y>=-2;y--){life();const b=bot.blockAt(q.offset(0,y,0)),pick=bot.inventory.items().find(i=>i.name.endsWith('_pickaxe'));if(pick&&!['dirt','grass_block','sand'].includes(b.name))await bot.equip(pick,'hand');else await bot.unequip('hand');await bot.dig(b,true,'raycast');steps++;for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12);k++)await tick(1);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12)throw Error('BURIAL_SETTLE')}for(let k=0;k<30&&!bot.inventory.items().some(i=>stableNames.includes(i.name));k++)await tick(1);const item=bot.inventory.items().find(i=>stableNames.includes(i.name));if(!item)throw Error('BURIAL_NO_CAP');await bot.equip(item,'hand');const rd=dirs.find(d=>full(bot.blockAt(q.plus(d))));if(!rd)throw Error('BURIAL_NO_ANCHOR');await bot._placeBlockWithOptions(bot.blockAt(q.plus(rd)),rd.scaled(-1),{forceLook:true});await tick(4);if(!shell(q.offset(0,-2,0)))throw Error('BURIAL_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-q.x-.5)<.85&&Math.abs(e.position.z-q.z-.5)<.85&&e.position.y>=q.y-2.5&&e.position.y<q.y);if(inside.length)throw Error('BURIAL_OCCUPIED_'+inside.map(e=>e.name));global.P1Overland=global.P1DownPending;global.P1DownPending=null;console.log('IN_PROGRAM_BURIAL_VERIFIED',reason,bot.entity.position,bot.health);return true;}catch(e){console.log('BURIAL_ERROR',steps,e.message,JSON.stringify({q,p:bot.entity.position,ground:bot.entity.onGround,v:bot.entity.velocity,blocks:[0,-1,-2].map(y=>[y,bot.blockAt(q.offset(0,y,0))?.name])}));if(steps===3&&await rescueCap())return true;throw e;}}
function guardedMovement(sprint=false){const hazards=foes();const m=new Movements(bot);m.canDig=true;for(const b of bot.registry.blocksArray)if(!b.name.endsWith('_leaves')&&!['snow','short_grass','fern'].includes(b.name))m.blocksCantBreak.add(b.id);m.canOpenDoors=false;m.allowSprinting=sprint;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=3;for(const n of['water','lava','fire','soul_fire','magma_block','sweet_berry_bush','powder_snow','cactus','nether_portal'])if(bot.registry.blocksByName[n])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);m.exclusionAreasStep.push(b=>{const p=b.position||new Vec3(b.x,b.y,b.z);let c=0;for(const e of hazards){if(Math.abs(e.position.y-p.y)>3&&!['skeleton','stray','witch'].includes(e.name))continue;const d=e.position.distanceTo(p),r=e.name==='creeper'?11:['skeleton','stray','witch'].includes(e.name)?16:7;if(d<r)c+=(r-d)*20;}return c});bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=500;}
async function guardedWalk(ms=60000,forceAfterMs=null,target={x:148.5,z:2212.5},nightTrial=false){const hp0=bot.health;let hurt=false,buried=false,phase='WALK',flee=false,lastPlan=0,started=Date.now(),last=bot.entity.position.clone(),progress=Date.now();const onHealth=()=>{if(bot.health<hp0-.25)hurt=true};bot.on('health',onHealth);try{guardedMovement();while(Date.now()-started<ms){life();if(Math.hypot(target.x-bot.entity.position.x,target.z-bot.entity.position.z)<.7){phase='TARGET';break}const e=contactThreat(),late=!nightTrial&&bot.time.timeOfDay>=10000,forced=forceAfterMs!==null&&Date.now()-started>=forceAfterMs;const shouldBury=e||hurt||late||forced||Date.now()-started>ms-8000;if(shouldBury){const why=e?'PROXIMITY_'+e.name:hurt?'HURT':late?'BEFORE_NIGHT':forced?'CONTROLLED':'BUDGET';if(await immediateBurial(why)||await surfaceBox(why)){buried=true;phase='BURIED';break}flee=!!e||hurt;}
if(Date.now()-lastPlan>1000||!bot.pathfinder.goal){let tx=target.x,tz=target.z;guardedMovement(flee);if(flee){const es=foes();let dx=0,dz=0;for(const h of es){const d=Math.max(1,h.position.distanceTo(bot.entity.position));dx+=(bot.entity.position.x-h.position.x)/(d*d);dz+=(bot.entity.position.z-h.position.z)/(d*d)}const len=Math.hypot(dx,dz)||1;tx=bot.entity.position.x+dx/len*24;tz=bot.entity.position.z+dz/len*24;}else if(Date.now()-progress>3000){tx=bot.entity.position.x+15;tz=bot.entity.position.z+12;progress=Date.now()}bot.pathfinder.setGoal(new goals.GoalXZ(Math.floor(tx),Math.floor(tz)));lastPlan=Date.now()}
if(bot.entity.position.distanceTo(last)>.7){last=bot.entity.position.clone();progress=Date.now()}if(bot.entity.isInWater){bot.pathfinder.setGoal(null);bot.setControlState('jump',true);await bot.lookAt(bot.entity.position.offset(target.x-bot.entity.position.x,1.4,target.z-bot.entity.position.z),true);bot.setControlState('forward',true)}await tick(1);}if(!buried&&!lost){if(await immediateBurial('FINAL')||await surfaceBox('FINAL')){buried=true;phase='BURIED'}}return{phase,buried,hurt,hp0,hp:bot.health};}finally{bot.removeListener('health',onHealth);bot.pathfinder.setGoal(null);bot.clearControlStates();if(bot.entity.isInWater)bot.setControlState('jump',true);}}
async function alignAxis(axis,target,max=45){for(let k=0;k<max&&Math.abs(bot.entity.position[axis]-target)>.045;k++){await bot.lookAt(bot.entity.position.offset(axis==="x"?Math.sign(target-bot.entity.position.x)*5:0,1.4,axis==="z"?Math.sign(target-bot.entity.position.z)*5:0),true);bot.setControlState("sneak",true);bot.setControlState("forward",true);await tick(1);bot.clearControlStates();await tick(2)}if(Math.abs(bot.entity.position[axis]-target)>.09)throw Error("ALIGN_ACTUAL "+axis)}
async function transit(mode){bot.pathfinder.setGoal(null);bot.clearControlStates();const d=new Vec3(6,67,81);if(bot.entity.position.distanceTo(d)>5)throw Error("DOOR_START_FAR");if(mode==="exit"){await alignAxis("x",6.59375);await alignAxis("z",82.6)}else await alignAxis("x",6.59375);let b=bot.blockAt(d);if(b.name!=="spruce_door"||b.getProperties().facing!=="north")throw Error("DOOR_GEOMETRY");if(!b.getProperties().open){await bot.activateBlock(b);await tick(7)}await bot.lookAt(bot.entity.position.offset(0,1.4,mode==="exit"?-10:10),true);bot.setControlState("forward",true);try{for(let k=0;k<80;k++){await tick(1);if(mode==="exit"?bot.entity.position.z<79.5:bot.entity.position.z>82.3)break}}finally{bot.clearControlStates()}await tick(5);if(mode==="exit"?bot.entity.position.z>=79.6:bot.entity.position.z<=82.15||(bot.entity.position.y<67||bot.entity.position.y>67.65))throw Error("TRANSIT_ACTUAL");b=bot.blockAt(d);if(b.getProperties().open){await bot.activateBlock(b);await tick(10)}if(bot.blockAt(d).getProperties().open)throw Error("DOOR_NOT_CLOSED");console.log("TRANSIT_CLOSED_ACTUAL",mode,bot.entity.position);bot.chat("P1_"+mode+"_ACTUAL_CLOSED door6 KEEP_P1_WRITER_UNTIL_OPERATION_END "+bot.entity.position+" HP"+bot.health+" no pendingdoorcontrols; nextfieldphaseown.");}

